const fs = require("node:fs");
const path = require("node:path");

const repositoryRoot = path.resolve(__dirname, "..", "..");
const legalDirectory = path.join(repositoryRoot, "docs", "legal");
const outputFile = path.join(__dirname, "..", "src", "legal", "generatedLegalDocuments.ts");

const documents = [
  ["privacy", "privacy-policy.md"],
  ["terms", "terms-of-service.md"],
  ["disclaimer", "gameplay-disclaimer.md"],
];

const source = [
  "// Generated from docs/legal by scripts/sync-legal-docs.js.",
  "// Do not edit this file directly; update the canonical Markdown and rerun the sync script.",
  "",
  'export type LegalDocumentKey = "privacy" | "terms" | "disclaimer";',
  "",
  "export const LEGAL_DOCUMENTS: Readonly<Record<LegalDocumentKey, string>> = {",
  ...documents.map(([key, filename]) => {
    const markdown = fs.readFileSync(path.join(legalDirectory, filename), "utf8").replace(/\r\n/g, "\n");
    return `  ${key}: ${JSON.stringify(markdown)},`;
  }),
  "};",
  "",
].join("\n");

fs.mkdirSync(path.dirname(outputFile), { recursive: true });
fs.writeFileSync(outputFile, source, "utf8");
